// Processar e normalizar dados das legislações
const items = $input.all();
const legislacoes = [];

// Processar dados do Senado
for (const item of items) {
  if (item.json.PesquisaBasicaMateria) {
    const materias = item.json.PesquisaBasicaMateria.Materias.Materia || [];
    const materiasArray = Array.isArray(materias) ? materias : [materias];

    for (const materia of materiasArray.slice(0, 5)) {
      legislacoes.push({
        fonte: 'senado',
        tipo: materia.SiglaTipoMateria,
        numero: materia.NumeroMateria,
        ano: materia.AnoMateria,
        ementa: materia.EmentaMateria,
        data_apresentacao: materia.DataApresentacao,
        url: `https://www25.senado.leg.br/web/atividade/materias/-/materia/${materia.CodigoMateria}`,
        id_origem: materia.CodigoMateria,
        autor: materia.NomeAutor || 'N/A'
      });
    }
  }

  // Processar dados da Câmara
  if (item.json.dados) {
    const proposicoes = item.json.dados || [];

    for (const prop of proposicoes.slice(0, 5)) {
      legislacoes.push({
        fonte: 'camara',
        tipo: prop.siglaTipo,
        numero: prop.numero,
        ano: prop.ano,
        ementa: prop.ementa,
        data_apresentacao: prop.dataApresentacao,
        url: `https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=${prop.id}`,
        id_origem: prop.id,
        autor: prop.autor || 'N/A'
      });
    }
  }
}

return legislacoes.map(leg => ({ json: leg }));

