// Extrair JSON da resposta do Gemini
const items = $input.all();
const processados = [];

for (const item of items) {
  try {
    // Resposta do Gemini vem em candidates[0].content.parts[0].text
    let responseText;

    if (item.json.candidates && item.json.candidates[0]) {
      // Formato Gemini
      responseText = item.json.candidates[0].content.parts[0].text;
    } else {
      // Fallback para outros formatos
      responseText = item.json.response || item.json.output || item.json.text;
    }

    console.log('Response text:', responseText);

    // Extrair JSON da resposta (procurar entre ```json e ```)
    const jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
    const jsonStr = jsonMatch ? jsonMatch[1] : responseText;

    // Tentar parsear JSON
    const analise = JSON.parse(jsonStr);

    processados.push({
      json: {
        ...item.json,
        analise_ia: analise,
        processado_em: new Date().toISOString()
      }
    });
  } catch (error) {
    console.error('Erro ao processar resposta:', error);
    console.error('Item completo:', JSON.stringify(item.json, null, 2));

    processados.push({
      json: {
        ...item.json,
        erro_processamento: error.message,
        resposta_bruta: item.json
      }
    });
  }
}

return processados;

// Aguardar processamento do vídeo D-ID
const videoId = $json.id;
const apiKey = $env.DID_API_KEY;

async function checkVideoStatus(id, key) {
  const maxAttempts = 30;
  const delayMs = 10000; // 10 segundos

  for (let i = 0; i < maxAttempts; i++) {
    const response = await fetch(`https://api.d-id.com/talks/${id}`, {
      headers: {
        'Authorization': `Basic ${key}`
      }
    });

    const data = await response.json();

    if (data.status === 'done') {
      return { json: { ...data, video_pronto: true } };
    } else if (data.status === 'error') {
      throw new Error(`Erro no D-ID: ${data.error}`);
    }

    // Aguardar antes da próxima tentativa
    await new Promise(resolve => setTimeout(resolve, delayMs));
  }

  throw new Error('Timeout aguardando vídeo');
}

return await checkVideoStatus(videoId, apiKey);

// Gerar caption otimizada para Instagram
const items = $input.all();
const result = [];

for (const item of items) {
  const analise = item.json.analise_ia;
  const leg = item.json;

  const caption = `🏛️ ${leg.tipo} ${leg.numero}/${leg.ano}

${analise.resumo_simples}

👥 Quem é impactado:
${analise.grupos_impactados.map((g, i) => `${i+1}. ${g}`).join('\n')}

💬 ${analise.pergunta_engajadora}

#LegisClara #Política #Cidadania #${leg.tipo}${leg.numero} #Brasil #Democracia #EducaçãoPolítica`;

  result.push({
    json: {
      ...item.json,
      caption_instagram: caption,
      hashtags: ['LegisClara', 'Política', 'Cidadania', 'Brasil', 'Democracia']
    }
  });
}

return result;

// Publicar Reel no Instagram (2 etapas)
const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const accessToken = $env.INSTAGRAM_ACCESS_TOKEN;
    const userId = $env.INSTAGRAM_USER_ID;
    const videoUrl = item.json.video_url_publica;
    const caption = item.json.caption_instagram;

    // ETAPA 1: Criar container de mídia
    const createResponse = await fetch(
      `https://graph.facebook.com/v18.0/${userId}/media`,
      {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          media_type: 'REELS',
          video_url: videoUrl,
          caption: caption,
          share_to_feed: true,
          access_token: accessToken
        })
      }
    );

    const createData = await createResponse.json();

    if (createData.error) {
      throw new Error(`Instagram API erro: ${createData.error.message}`);
    }

    const containerId = createData.id;
    console.log('Container criado:', containerId);

    // ETAPA 2: Aguardar upload e publicar
    let attempts = 0;
    const maxAttempts = 30;

    while (attempts < maxAttempts) {
      // Checar status do container
      const statusResponse = await fetch(
        `https://graph.facebook.com/v18.0/${containerId}?fields=status_code&access_token=${accessToken}`
      );
      const statusData = await statusResponse.json();

      if (statusData.status_code === 'FINISHED') {
        // Publicar!
        const publishResponse = await fetch(
          `https://graph.facebook.com/v18.0/${userId}/media_publish`,
          {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              creation_id: containerId,
              access_token: accessToken
            })
          }
        );

        const publishData = await publishResponse.json();

        if (publishData.error) {
          throw new Error(`Erro ao publicar: ${publishData.error.message}`);
        }

        // Sucesso!
        results.push({
          json: {
            ...item.json,
            id: publishData.id,
            permalink: `https://www.instagram.com/p/${publishData.id}/`,
            status: 'publicado'
          }
        });

        break;
      } else if (statusData.status_code === 'ERROR') {
        throw new Error('Erro no processamento do vídeo pelo Instagram');
      }

      // Aguardar 10 segundos antes de checar novamente
      await new Promise(resolve => setTimeout(resolve, 10000));
      attempts++;
    }

    if (attempts >= maxAttempts) {
      throw new Error('Timeout aguardando processamento do vídeo');
    }

  } catch (error) {
    console.error('Erro ao publicar no Instagram:', error);
    results.push({
      json: {
        ...item.json,
        status: 'erro',
        erro_msg: error.message
      }
    });
  }
}

return results;

